class Ops:
    """The generated methods (see the module docstring)."""

    def _op(self, name: str, positionals: Sequence[Any], flags: Mapping[str, Any]) -> Any:  # defined by Artgen
        raise NotImplementedError

    def init(self) -> "Result":
        """Scaffold art/ in a game repo: direction, briefs, ledger and config. (artgen init)"""
        return self._op("init", [], {})

    def direction_candidates(self, *, pitch: Optional[str] = None, view: Optional[str] = None, mood: Optional[Sequence[str]] = None, scale: Optional[str] = None, directions: Optional[float] = None, id: Optional[str] = None, colors: Optional[str] = None, background: Optional[str] = None, from_: Optional[str] = None) -> "Result":
        """Write the art-direction candidates for a game pitch, with probe assets to judge them by. (artgen direction candidates)"""
        return self._op("direction.candidates", [], {"pitch": pitch, "view": view, "mood": mood, "scale": scale, "directions": directions, "id": id, "colors": colors, "background": background, "from_": from_})

    def direction_show(self, *, candidate: Optional[str] = None) -> "Result":
        """Show the locked direction, the candidates, the style tiles and the probes (or one candidate with --candidate). (artgen direction show)"""
        return self._op("direction.show", [], {"candidate": candidate})

    def direction_tile(self, *candidates: str) -> "Result":
        """Render the probe set under each candidate into one style tile sheet. (artgen direction tile)"""
        return self._op("direction.tile", [*candidates], {})

    def direction_mix(self, base: str, *, palette: Optional[str] = None, line: Optional[str] = None, shading: Optional[str] = None, scale: Optional[str] = None, detail: Optional[str] = None, camera: Optional[str] = None, theme: Optional[str] = None, pipeline: Optional[str] = None, effects: Optional[str] = None, rules: Optional[str] = None, name: Optional[str] = None) -> "Result":
        """Mix a new candidate from parts of existing ones. (artgen direction mix)"""
        return self._op("direction.mix", [base], {"palette": palette, "line": line, "shading": shading, "scale": scale, "detail": detail, "camera": camera, "theme": theme, "pipeline": pipeline, "effects": effects, "rules": rules, "name": name})

    def direction_lock(self, candidate: str, *, note: Optional[str] = None, id: Optional[str] = None) -> "Result":
        """Lock a candidate as the project's art direction: save the anchors and art/direction.png. (artgen direction lock)"""
        return self._op("direction.lock", [candidate], {"note": note, "id": id})

    def direction_anchors(self) -> "Result":
        """Re-save the anchors from the probes (after their full pipeline). (artgen direction anchors)"""
        return self._op("direction.anchors", [], {})

    def direction_new(self, *, from_: Optional[str] = None, name: Optional[str] = None) -> "Result":
        """Start a draft direction from the locked one (a version change). (artgen direction new)"""
        return self._op("direction.new", [], {"from_": from_, "name": name})

    def direction_validate(self, file: str) -> "Result":
        """Check a direction file against the direction format. (artgen direction validate)"""
        return self._op("direction.validate", [file], {})

    def palette_import(self, file: str, *, n: Optional[float] = None, interview: Optional[bool] = None, swatch: Optional[str] = None) -> "Result":
        """Read a palette file and print its colours and ramps. (artgen palette import)"""
        return self._op("palette.import", [file], {"n": n, "interview": interview, "swatch": swatch})

    def palette_extract(self, file: str, *, n: Optional[float] = None, interview: Optional[bool] = None, swatch: Optional[str] = None) -> "Result":
        """Extract the dominant colours of an image and print its colours and ramps. (artgen palette extract)"""
        return self._op("palette.extract", [file], {"n": n, "interview": interview, "swatch": swatch})

    def palette_ramp(self, hex: str, *, steps: Optional[float] = None, hue_shift: Optional[float] = None, contrast: Optional[float] = None) -> "Result":
        """A colour ramp from one colour. (artgen palette ramp)"""
        return self._op("palette.ramp", [hex], {"steps": steps, "hue_shift": hue_shift, "contrast": contrast})

    def new(self, id: str, *, kind: Optional[str] = None, view: Optional[str] = None, size: Optional[str] = None, states: Optional[Sequence[str]] = None, directions: Optional[float] = None, notes: Optional[str] = None, dir: Optional[str] = None) -> "Result":
        """Scaffold an asset directory (base.v1.js and its brief) from the template for its kind and view. (artgen new)"""
        return self._op("new", [id], {"kind": kind, "view": view, "size": size, "states": states, "directions": directions, "notes": notes, "dir": dir})

    def pass_status(self, asset: str, *, direction: Optional[str] = None, ledger: Optional[str] = None) -> "Result":
        """Pipeline state of an asset: versions, scores, gate, best base and the next step. (artgen pass status)"""
        return self._op("pass.status", [asset], {"direction": direction, "ledger": ledger})

    def pass_next(self, asset: str, *, direction: Optional[str] = None, ledger: Optional[str] = None) -> "Result":
        """The next step of an asset's pipeline. (artgen pass next)"""
        return self._op("pass.next", [asset], {"direction": direction, "ledger": ledger})

    def render(self, asset: str, *, version: Optional[str] = None, variant: Optional[int] = None, stages: Optional[bool] = None, direction: Optional[str] = None, ledger: Optional[str] = None) -> "Result":
        """Render one version of an asset and run the conformance gate. (artgen render)"""
        return self._op("render", [asset], {"version": version, "variant": variant, "stages": stages, "direction": direction, "ledger": ledger})

    def review(self, asset: str, *, version: Optional[str] = None, blind: Optional[bool] = None, detail: Optional[str] = None, scene: Optional[bool] = None, direction: Optional[str] = None, ledger: Optional[str] = None) -> "Result":
        """Build the review sheet for a version and log it to the ledger. (artgen review)"""
        return self._op("review", [asset], {"version": version, "blind": blind, "detail": detail, "scene": scene, "direction": direction, "ledger": ledger})

    def conformance(self, asset: str, *, version: Optional[str] = None, direction: Optional[str] = None, ledger: Optional[str] = None) -> "Result":
        """Run the conformance gate on a version (nothing is written). (artgen conformance)"""
        return self._op("conformance", [asset], {"version": version, "direction": direction, "ledger": ledger})

    def score(self, asset: str, version: str, score: float, *, note: Optional[str] = None, reviewer: Optional[str] = None, blind: Optional[bool] = None, model: Optional[str] = None, effort: Optional[str] = None, tokens_in: Optional[float] = None, tokens_out: Optional[float] = None, agent_tokens_in: Optional[float] = None, ms: Optional[float] = None, direction: Optional[str] = None, ledger: Optional[str] = None) -> "Result":
        """Record a 0-10 visual score for a reviewed version, with its gate results and token estimates. (artgen score)"""
        return self._op("score", [asset, version, score], {"note": note, "reviewer": reviewer, "blind": blind, "model": model, "effort": effort, "tokens_in": tokens_in, "tokens_out": tokens_out, "agent_tokens_in": agent_tokens_in, "ms": ms, "direction": direction, "ledger": ledger})

    def variants(self, asset: str, *, version: Optional[str] = None, n: Optional[float] = None, direction: Optional[str] = None, ledger: Optional[str] = None) -> "Result":
        """A sheet of seed variants of a version, with how many are distinct. (artgen variants)"""
        return self._op("variants", [asset], {"version": version, "n": n, "direction": direction, "ledger": ledger})

    def bench_report(self, dir: str, *, out: Optional[str] = None, title: Optional[str] = None) -> "Result":
        """A markdown report on every asset directory under a folder (benchmark runs). (artgen bench-report)"""
        return self._op("bench-report", [dir], {"out": out, "title": title})

    def finish(self, asset: str, *, base: Optional[str] = None, direction: Optional[str] = None, ledger: Optional[str] = None) -> "Result":
        """Write the next finish.vM.js from the template, bound to the best scored base. (artgen finish)"""
        return self._op("finish", [asset], {"base": base, "direction": direction, "ledger": ledger})

    def make(self, *ids: str, parallel: Optional[float] = None, wave: Optional[float] = None) -> "Result":
        """One tick of the autonomous run: scaffold, mark finals, hold v2 for the v1 roster and name the next step. (artgen make)"""
        return self._op("make", [*ids], {"parallel": parallel, "wave": wave})

    def brief_lint(self, *ids: str) -> "Result":
        """Warnings for briefs before any drawing starts: materials their kind's ramps leave out, views with no template. (artgen brief lint)"""
        return self._op("brief.lint", [*ids], {})

    def brief_add(self, id: str, *, kind: Optional[str] = None, view: Optional[str] = None, size: Optional[str] = None, states: Optional[Sequence[str]] = None, directions: Optional[float] = None, anims: Optional[Sequence[str]] = None, durations: Optional[Sequence[str]] = None, variants: Optional[float] = None, swaps: Optional[Sequence[str]] = None, importance: Optional[Literal["hero", "standard", "filler"]] = None, priority: Optional[float] = None, height: Optional[float] = None, body: Optional[str] = None, object: Optional[str] = None, notes: Optional[str] = None, break_contract: Optional[bool] = None) -> "Result":
        """Add a brief to art/briefs.yaml: the asset to make (id, kind, view, size, states, animations, …). (artgen brief add)"""
        return self._op("brief.add", [id], {"kind": kind, "view": view, "size": size, "states": states, "directions": directions, "anims": anims, "durations": durations, "variants": variants, "swaps": swaps, "importance": importance, "priority": priority, "height": height, "body": body, "object": object, "notes": notes, "break_contract": break_contract})

    def brief_list(self) -> "Result":
        """List the briefs in art/briefs.yaml. (artgen brief list)"""
        return self._op("brief.list", [], {})

    def brief_rm(self, id: str) -> "Result":
        """Remove a brief (the asset sources are kept). (artgen brief rm)"""
        return self._op("brief.rm", [id], {})

    def status(self, *ids: str) -> "Result":
        """Production status of every brief: brief, in-pipeline, final, approved, exported, with revision and stale. (artgen status)"""
        return self._op("status", [*ids], {})

    def gallery(self, *ids: str) -> "Result":
        """A sheet of finished assets for the user: score, open issues, BELOW BAR. (artgen gallery)"""
        return self._op("gallery", [*ids], {})

    def sheet(self, id: str) -> "Result":
        """The asset's one-page data sheet: kind, size, states, facings, frames, template, budget, palette, contract, references. (artgen sheet)"""
        return self._op("sheet", [id], {})

    def feedback(self, id: str, *, route: Optional[str] = None, note: Optional[str] = None, by: Optional[str] = None, region: Optional[Sequence[float]] = None, cell: Optional[str] = None, force: Optional[bool] = None, via: Optional[str] = None) -> "Result":
        """Record feedback on a finished asset and open a revision. (artgen feedback)"""
        return self._op("feedback", [id], {"route": route, "note": note, "by": by, "region": region, "cell": cell, "force": force, "via": via})

    def approve(self, id: str, *, note: Optional[str] = None, via: Optional[str] = None) -> "Result":
        """Record the user's approval of a final asset (a passing gate and a review sheet are needed). (artgen approve)"""
        return self._op("approve", [id], {"note": note, "via": via})

    def roster(self, *ids: str, seed: Optional[float] = None, stage: Optional[str] = None) -> "Result":
        """Contact sheets of the roster for a fresh reviewer: sizes against briefs, the most similar silhouettes. (artgen roster)"""
        return self._op("roster", [*ids], {"seed": seed, "stage": stage})

    def roster_record(self, file: str, *, reviewer: Optional[str] = None) -> "Result":
        """Record a roster review's notes as open issues on the assets. (artgen roster record)"""
        return self._op("roster.record", [file], {"reviewer": reviewer})

    def texture(self, material: Optional[str] = None, *, size: Optional[str] = None, seed: Optional[float] = None, ramps: Optional[Sequence[str]] = None, scale: Optional[float] = None, list: Optional[bool] = None, out: Optional[str] = None, direction: Optional[str] = None) -> "Result":
        """Render a material recipe under the direction: tile, normal map and a 3×3 repeat preview. (artgen texture)"""
        return self._op("texture", [material], {"size": size, "seed": seed, "ramps": ramps, "scale": scale, "list": list, "out": out, "direction": direction})

    def fx(self, preset: Optional[str] = None, *, size: Optional[str] = None, frames: Optional[float] = None, seed: Optional[float] = None, scale: Optional[float] = None, list: Optional[bool] = None, out: Optional[str] = None, direction: Optional[str] = None) -> "Result":
        """Quick look at a particle preset: a frame strip, an onion-skin sheet and GIF/APNG files. (artgen fx)"""
        return self._op("fx", [preset], {"size": size, "frames": frames, "seed": seed, "scale": scale, "list": list, "out": out, "direction": direction})

    def trace_base(self, asset: str, image: str, *, mat: Optional[str] = None, margin: Optional[float] = None, anchor: Optional[Literal["center", "bottom"]] = None, threshold: Optional[str] = None, invert: Optional[bool] = None, blur: Optional[int] = None, smoothing: Optional[int] = None, simplify: Optional[float] = None, min_area: Optional[float] = None, holes: Optional[bool] = None, max_paths: Optional[int] = None, alpha: Optional[bool] = None, direction: Optional[str] = None, ledger: Optional[str] = None) -> "Result":
        """Write an asset's next base.vN.js from a traced sketch or reference picture: its shapes as path primitives, fitted to the asset's frame. (artgen trace-base)"""
        return self._op("trace-base", [asset, image], {"mat": mat, "margin": margin, "anchor": anchor, "threshold": threshold, "invert": invert, "blur": blur, "smoothing": smoothing, "simplify": simplify, "min_area": min_area, "holes": holes, "max_paths": max_paths, "alpha": alpha, "direction": direction, "ledger": ledger})

    def cut(self, target: str, *, out: Optional[str] = None, fill: Optional[Literal["art", "flat"]] = None, color: Optional[str] = None, padding: Optional[int] = None, square: Optional[bool] = None, scale: Optional[int] = None, version: Optional[str] = None, draft: Optional[bool] = None, state: Optional[str] = None, facing: Optional[str] = None, frame: Optional[int] = None, threshold: Optional[str] = None, invert: Optional[bool] = None, smoothing: Optional[int] = None, keep_all: Optional[bool] = None, direction: Optional[str] = None, ledger: Optional[str] = None) -> "Result":
        """Cut a token (or the flat silhouette the Shape gate reads) from an approved asset's render, or from a picture. (artgen cut)"""
        return self._op("cut", [target], {"out": out, "fill": fill, "color": color, "padding": padding, "square": square, "scale": scale, "version": version, "draft": draft, "state": state, "facing": facing, "frame": frame, "threshold": threshold, "invert": invert, "smoothing": smoothing, "keep_all": keep_all, "direction": direction, "ledger": ledger})

